	simde_mm_store_si128((simde__m128i*)REX_RAW_ADDR_W(ea, 16), simde_mm_shuffle_epi8(simde_mm_load_si128((simde__m128i*)ctx.v11.u8), simde_mm_load_si128((simde__m128i*)VectorMaskL)));
	// addi r1,r1,112
